param([Parameter(Mandatory=$true)][string]$Admission,[switch]$ExecutionAuthorized)
# One future Prepare only: no solver, reader, GenCase, build, restart or automatic next action.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$seed=Join-Path $tests 'outputs\upl_damp_step_seed_r1';$record=Join-Path $logs 'upl_damp_step_r1.inputs.json';$ci=[Globalization.CultureInfo]::InvariantCulture
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need ($e.path -and $e.sha256) 'Missing Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function Dom([string]$p){$x=New-Object Xml.XmlDocument;$x.PreserveWhitespace=$false;$x.Load($p);return ,$x}
function One($x,[string]$path){$n=$x.SelectNodes($path);Need ($n.Count -eq 1) ('Expected one XML node: '+$path);return ,$n[0]}
function Number([string]$v){[double]::Parse($v,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture)}
function SaveXml($x,[string]$p){$declaration=$x.FirstChild.OuterXml;$s=New-Object Xml.XmlWriterSettings;$s.OmitXmlDeclaration=$true;$s.Indent=$true;$s.IndentChars='    ';$s.NewLineChars="`n";$s.NewLineHandling=[Xml.NewLineHandling]::Replace;$body=New-Object Text.StringBuilder;$w=[Xml.XmlWriter]::Create($body,$s);try{$x.Save($w)}finally{$w.Dispose()};[IO.File]::WriteAllText($p,($declaration+"`n"+$body.ToString()),(New-Object Text.UTF8Encoding($false)))}
# Independent literal JDsOutputTime::GetNextTime replay, including anchor clamp/cache.
function NextTime([double]$t,$state,$segments){
  if($state.last_input -ge 0 -and $t -eq $state.last_input){return $state.last_output};$state.last_input=$t;$tb=[double]$segments[$state.base].time;$nextAnchor=[double]::MaxValue;if($state.base+1 -lt $segments.Count){$nextAnchor=[double]$segments[$state.base+1].time}
  while($t -ge $nextAnchor){$state.base++;$tb=[double]$segments[$state.base].time;$nextAnchor=[double]::MaxValue;if($state.base+1 -lt $segments.Count){$nextAnchor=[double]$segments[$state.base+1].time}}
  if($t -lt $tb){$next=$tb}else{$cadence=[double]$segments[$state.base].timeout;$nt=[long][Math]::Floor(($t-$tb)/$cadence);$next=$tb+$cadence*$nt;while($next -le $t){$next=$tb+$cadence*$nt;$nt++};if($next -gt $nextAnchor){$next=$nextAnchor}};$state.last_output=[double]$next;return [double]$next
}
function Schedule([bool]$half){
  $dc=[Math]::Pow(2,-18);$factor=if($half){2}else{1};$dt=$dc/$factor;$steps=131072*$factor;$expected=New-Object 'Collections.Generic.SortedSet[int]'
  for($k=0;$k -le 32768;$k+=32){[void]$expected.Add($k*$factor)};for($k=2560;$k -le 2688;$k++){[void]$expected.Add($k*$factor)};for($k=33280;$k -le 131072;$k+=512){[void]$expected.Add($k*$factor)}
  $segments=@(@{time=0.0;timeout=32*$dc},@{time=2560*$dc;timeout=$dc},@{time=2688*$dc;timeout=32*$dc},@{time=32768*$dc;timeout=512*$dc});$state=@{base=0;last_input=-1.0;last_output=0.0};$rows=New-Object 'Collections.Generic.List[object]';[void]$rows.Add([ordered]@{part=0;completed_steps=0;saved_step=0;time_s=0.0});$t=0.0;$next=NextTime 0.0 $state $segments
  for($completed=1;$completed -le $steps;$completed++){$t+=$dt;if($t -ge $next -or $completed -eq $steps){[void]$rows.Add([ordered]@{part=$rows.Count;completed_steps=$completed;saved_step=$completed-1;time_s=[double]$t});$next=NextTime $t $state $segments}}
  $wanted=@($expected);Need ($rows.Count -eq 1341 -and $wanted.Count -eq 1341 -and $t -eq 0.5) 'Candidate scheduler/count differs'
  for($i=0;$i -lt 1341;$i++){Need ($rows[$i].part -eq $i -and $rows[$i].completed_steps -eq $wanted[$i] -and $rows[$i].saved_step -eq $(if($i){$wanted[$i]-1}else{0}) -and [BitConverter]::DoubleToInt64Bits($rows[$i].time_s) -eq [BitConverter]::DoubleToInt64Bits([double]$wanted[$i]*$dt)) 'Replayed candidate native schedule differs'}
  Need ($rows[141].completed_steps -eq 2621*$factor -and $rows[1148].time_s -eq 0.125 -and @($rows|Where-Object{$_.time_s -le 0.125}).Count -eq 1149 -and @($rows|Where-Object{$_.completed_steps -gt 2621*$factor}).Count -eq 1199) 'Candidate event/bracket/post-open counts differ'
  return [ordered]@{table=$rows.ToArray();segments=$segments;dt=$dt;steps=$steps;factor=$factor}
}
Need $ExecutionAuthorized.IsPresent 'Root full read and explicit Prepare authorization required';Fresh @($seed,$record)
$gateEntry=E $Admission;$gate=J $gateEntry.path;Need ($gate.stage -ceq 'upl_damp_step_prepare_admission_r1' -and $gate.passed -and $gate.physical_acceptance -eq $false -and @($gate.allowed_actions).Count -eq 1 -and $gate.allowed_actions[0] -ceq 'prepare' -and @($gate.inputs).Count -gt 0) 'Explicit singleton Prepare admission required';V $gate.inputs
$proofs=@();foreach($case in @('coarse_prefix','half_prefix','half')){$e=E (Join-Path $logs ('upl_damp_long_'+$case+'_r1.check.json'));$v=J $e.path;Need ($v.stage -ceq 'upl_damp_long_compare_r1' -and $v.case -ceq $case -and $v.passed -and $v.physical_acceptance -eq $false) 'Completed current .5s comparison required';$keys=if($case -ceq 'half'){@('pressure_RMS_all_times_le_5Pa','material_XYZ_difference_all_times_le_0_005mm','actual_time_difference_le_1e_minus14_s')}else{@('all5_binary_payload_prefix_exact','all3_identity_files_exact','all3_text_prefix_exact','same_build_program')};foreach($key in $keys){Need ($v.gates.$key -eq $true) ('Original prerequisite gate failed: '+$key)};V $v.files;$proofs+=@{entry=$e;value=$v}}
Need ($proofs[2].value.samples -eq 1469 -and $proofs[0].value.compared_prefix_samples -eq 1277 -and $proofs[1].value.compared_prefix_samples -eq 1277 -and $proofs[0].value.long_samples -eq 1469 -and $proofs[1].value.long_samples -eq 1469 -and @($proofs[2].value.prefix_checks).Count -eq 2 -and $proofs[2].value.prefix_checks[0].sha256 -ceq $proofs[0].entry.sha256 -and $proofs[2].value.prefix_checks[1].sha256 -ceq $proofs[1].entry.sha256) 'Current half/prefix proof identity differs'
$plotEntry=E (Join-Path $logs 'upl_damp_long_plot_r1.check.json');$plot=J $plotEntry.path;Need ($plot.stage -ceq 'upl_damp_long_plot_r1' -and $plot.passed -and $plot.physical_acceptance -eq $false) 'Completed .5s descriptive figures required';V $plot.files
foreach($e in @($proofs|ForEach-Object{$_.entry})+@($plotEntry)){Need (@($gate.inputs|Where-Object{$_.path -ceq $e.path -and $_.bytes -eq $e.bytes -and $_.sha256 -ceq $e.sha256}).Count -eq 1) 'Root admission must bind each exact .5s prefix/half/figure proof'}
$buildEntry=E (Join-Path $logs 'upl_damp_ReleaseCPU_r2.build.json');$b=J $buildEntry.path;Need ($b.passed -and $b.stage -ceq 'upl_damp_build_r2' -and $b.configuration -ceq 'ReleaseCPU' -and $b.source_bindings_unchanged -and $b.canonical_programs_unchanged -and $b.runtime_unchanged -and $b.exact_object_basename_closure -and @($b.objects).Count -eq 86 -and @($b.source_snapshot).Count -eq 265 -and @($b.runtime).Count -eq 4 -and @($b.canonical_programs_before).Count -eq 7) 'Current unchanged CPU main build/source closure required'
foreach($proof in $proofs){Need (@($proof.value.source_builds).Count -eq 2) 'Prerequisite source-build pair missing';foreach($e in $proof.value.source_builds){Need ($e.path -ceq $buildEntry.path -and $e.bytes -eq $buildEntry.bytes -and $e.sha256 -ceq $buildEntry.sha256) 'Completed scientific proofs use another source build'}}
$call=J $b.project_call.path;Need ($call.owned_call_exited -and $call.typed_LASTEXITCODE_captured_immediately -and $call.exit_code -is [int] -and $call.exit_code -eq 0 -and !$call.invocation_failure) 'Original authoritative project typed exit0 required'
$oldEntry=E (Join-Path $logs 'upl_damp_long_r1.inputs.json');$old=J $oldEntry.path;$scheduler=E (Join-Path (Join-Path $tests '..\..\..\..\src') 'source\JDsOutputTime.cpp');Need ($old.stage -ceq 'upl_damp_long_prepare_r1' -and $old.passed -and $old.prepared -and !$old.physical_acceptance -and $scheduler.sha256 -ceq 'b26c1b87f090b28bdc72c28d6ed7dfeee0ad7a0bcd28eb428f1ae72716d0c72f') 'Sealed completed long inputs/unchanged scheduler required'
$inputs=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_step_r1.json')),$gateEntry,$buildEntry,$b.project_call,$b.program,$oldEntry,$scheduler,$plotEntry)+@($proofs|ForEach-Object{$_.entry})+@($gate.inputs)+@($b.canonical_programs_before);foreach($p in @($b.source_snapshot)+@($b.documentation_snapshot,$b.case_readme_snapshot)){$inputs+=@($p.original,$p.snapshot)};foreach($p in $b.runtime){$inputs+=@($p.original,$p.copy)}
$candidateEvent=2621*[Math]::Pow(2,-18);$plans=@();$fresh=@();foreach($window in @('coarse','half')){
  $rows=@($old.jobs|Where-Object{$_.window -ceq $window});Need ($rows.Count -eq 1) 'Unique completed long input required';$o=$rows[0];Need ($o.damping -eq 1 -and $o.damping_coef -eq 0.02 -and $o.end_s -eq 0.5 -and $o.expected_samples -eq 1469 -and $o.dt_s -eq [Math]::Pow(2,$(if($window -ceq 'half'){-20}else{-19})) -and $o.configuration.sha256 -ceq $o.runtime.sha256 -and $o.initial_BI4.sha256 -ceq 'f2836ffeb049fc777de7687608dd5dfbece81f78440bdc01f21890ee3e3fedac' -and $o.normals.sha256 -ceq '0509139e4fee0c57d3b480f213c4b9062cf467ce6a24c0a1d13d87148a885f97') 'Completed material/seed/clock differs'
  $configuration=Join-Path $tests ('configs\upl_damp_step_'+$window+'_r1.xml');$prefix=Join-Path $seed ('upl_damp_step_'+$window+'_r1');$fresh+=@($configuration,($prefix+'.xml'),($prefix+'.bi4'),($prefix+'_Normals.nbi4'));$plans+=@{window=$window;old=$o;configuration=$configuration;prefix=$prefix;schedule=(Schedule ($window -ceq 'half'))};$inputs+=@($o.configuration,$o.runtime,$o.initial_BI4,$o.normals)
}
for($i=0;$i -lt 1341;$i++){Need ($plans[1].schedule.table[$i].completed_steps -eq 2*$plans[0].schedule.table[$i].completed_steps -and [BitConverter]::DoubleToInt64Bits($plans[1].schedule.table[$i].time_s) -eq [BitConverter]::DoubleToInt64Bits($plans[0].schedule.table[$i].time_s)) 'Candidate coarse/half binary clocks differ'}
Fresh $fresh;V $inputs;$jobs=@();$files=@();$failure=$null;$unchanged=$false
try{[void](New-Item -ItemType Directory -Path $seed);foreach($p in $plans){
  $o=$p.old;$x=Dom $o.runtime.path;$before=$x.OuterXml;$hydro='/case/execution/special/hydromechanics/';$parameters='/case/execution/parameters/parameter[@key="'
  foreach($item in @(@{path=$hydro+'HydroMechDynamicSeepage';value=1},@{path=$hydro+'HydroMechConductivityModel';value=0},@{path=$hydro+'HydroMechConductivityCk';value=0},@{path=$hydro+'HydroMechTopLoadQ0';value=10000},@{path=$parameters+'TimeMax"]';value=0.5},@{path=$parameters+'SoilDamping"]';value=1},@{path=$parameters+'SoilDampingCoef"]';value=0.02})){Need ((Number ((One $x $item.path).GetAttribute('value'))) -eq $item.value) 'Retained physical value differs'}
  $changes=@();foreach($path in @(($parameters+'DtIni"]'),($parameters+'DtFixed"]'),($hydro+'HydroMechTopLoadRampTime'),($hydro+'HydroMechDrainageStartTime'))){$node=One $x $path;$oldValue=$node.GetAttribute('value');$isDt=$path.Contains('Dt');$wanted=if($isDt){$p.schedule.dt}else{$candidateEvent};Need ((Number $oldValue) -eq $(if($isDt){$o.dt_s}else{5243*[Math]::Pow(2,-19)})) 'Original changed-node value differs';$node.SetAttribute('value',$wanted.ToString('R',$ci));$changes+=@{xpath=$path;attribute='value';old_value=$oldValue;new_value=$node.GetAttribute('value')}}
  $timeoutNode=One $x '/case/execution/special/timeout';$nodes=$timeoutNode.SelectNodes('tout');Need ($nodes.Count -eq 4) 'Retained four timeout nodes required';for($i=0;$i -lt 4;$i++){Need ((Number $nodes[$i].GetAttribute('time')) -eq $p.schedule.segments[$i].time -and (Number $nodes[$i].GetAttribute('timeout')) -eq $(if($i -eq 1){[Math]::Pow(2,-19)}else{$p.schedule.segments[$i].timeout})) 'Retained ordinary cadence/anchors differ'}
  $oldDense=$nodes[1].GetAttribute('timeout');$nodes[1].SetAttribute('timeout',([Math]::Pow(2,-18)).ToString('R',$ci));$changes+=@{xpath='/case/execution/special/timeout/tout[2]';attribute='timeout';old_value=$oldDense;new_value=$nodes[1].GetAttribute('timeout')};SaveXml $x $p.configuration
  $inverse=Dom $p.configuration;foreach($change in $changes){(One $inverse $change.xpath).SetAttribute($change.attribute,$change.old_value)};Need ($inverse.OuterXml -ceq $before) 'Changes outside DtIni/DtFixed/ramp/drain/dense timeout'
  Copy-Item -LiteralPath $p.configuration -Destination ($p.prefix+'.xml');Copy-Item -LiteralPath $o.initial_BI4.path -Destination ($p.prefix+'.bi4');Copy-Item -LiteralPath $o.normals.path -Destination ($p.prefix+'_Normals.nbi4')
  $ce=E $p.configuration;$re=E ($p.prefix+'.xml');$be=E ($p.prefix+'.bi4');$ne=E ($p.prefix+'_Normals.nbi4');Need ($ce.sha256 -ceq $re.sha256 -and $be.sha256 -ceq $o.initial_BI4.sha256 -and $be.bytes -eq $o.initial_BI4.bytes -and $ne.sha256 -ceq $o.normals.sha256 -and $ne.bytes -eq $o.normals.bytes) 'Fresh runtime/seed copy differs'
  $jobs+=@{window=$p.window;configuration=$ce;runtime=$re;initial_BI4=$be;normals=$ne;input_prefix=$p.prefix;dt_s=$p.schedule.dt;end_s=0.5;steps=$p.schedule.steps;expected_samples=1341;required_CLI=@('-mdbc_freeslip','-svres',('-nsteps:'+$p.schedule.steps));damping=1;damping_coef=0.02;source_manifest=$oldEntry;source_configuration=$o.configuration;source_runtime=$o.runtime;inverse_DOM_exact=$true;only_declared_clock_event_changes=$true;changes=$changes;saved_clock_table=$p.schedule.table;special_timeout=$p.schedule.segments;samples_through_0p125=1149;event_completed_step=2621*$p.schedule.factor;ramp_and_drain_event_s=$candidateEvent;event_part=141;first_post_open_part=142;post_open_frames=1199;post_open_drained_particle_checks_expected=11990;necessary_current_state_step_bound_still_required=$true;initial_particle_fields_rewritten=$false;old_trajectory_prefix_equivalence_claimed=$false};$files+=@($ce,$re,$be,$ne)
}}catch{$failure=$_.Exception.Message}
try{V $inputs;V $files;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
$passed=(!$failure -and $unchanged -and $jobs.Count -eq 2 -and $files.Count -eq 8);$result=[ordered]@{stage='upl_damp_step_prepare_r1';passed=[bool]$passed;prepared=[bool]$passed;admission=$gateEntry;source_build=$buildEntry;source_snapshot=$b.source_snapshot;source_program=$b.program;completed_long_half=$proofs[2].entry;completed_long_prefixes=@($proofs[0].entry,$proofs[1].entry);completed_long_plot=$plotEntry;jobs=$jobs;inputs=$inputs;files=$files;seed_directory=$seed;source_scheduler=$scheduler;sample_count=1341;samples_through_0p125=1149;post_open_frames=1199;ramp_and_drain_event_s=$candidateEvent;old_event_s=5243*[Math]::Pow(2,-19);event_change_s=($candidateEvent-5243*[Math]::Pow(2,-19));q0_changed=$false;new_experiment=$true;paired_times_bit_exact=$true;deserialized_JSON_rowtime_used_as_clock_truth=$false;input_sources_unchanged=$unchanged;old_half_or_prefix_adopted=$false;solver_reader_or_build_invoked=$false;formal_files_changed=$false;physical_acceptance=$false;failure=$failure}
Fresh @($record);[IO.File]::WriteAllText($record,($result|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)));if(!$passed){throw "Candidate Prepare rejected; preserve $record/partials and retain accepted old dt"};Write-Output "Two new step-candidate inputs prepared only: $record"
